  "implementation": "def solve(case):
    lines = case.get('lines', [])
    valid = True
    error_line = None
    trajectory = []
    state = 0  # 0: start, 1: after Thought, 2: after Action, 3: after Observation, 4: after Final
    for i, line in enumerate(lines):
        colon_pos = line.find(':')
        if colon_pos == -1:
            type_str = None
            content = line
        else:
            type_str = line[:colon_pos].strip()
            content = line[colon_pos+1:].strip()
        if type_str not in {'Thought', 'Action', 'Observation', 'Final'}:
            valid = False
            error_line = i
            break
        if state == 0:
            if type_str != 'Thought':
                valid = False
                error_line = i
                break
            state = 1
        elif state == 1:
            if type_str == 'Action':
                state = 2
            elif type_str == 'Final':
                state = 4
            else:
                valid = False
                error_line = i
                break
        elif state == 2:
            if type_str != 'Observation':
                valid = False
                error_line = i
                break
            state = 3
        elif state == 3:
            if type_str != 'Thought':
                valid = False
                error_line = i
                break
            state = 1
        elif state == 4:
            valid = False
            error_line = i
            break
        trajectory.append({'type': type_str, 'content': content})
    else:
        if state != 4:
            valid = False
            error_line = len(lines) - 1 if lines else 0
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}
